node -e "
const db = require('better-sqlite3')('/workspace/world.db');

// Look for product PROD-2028EE
let row = db.prepare(\"SELECT * FROM products WHERE product_id = 'PROD-2028EE'\").get();
console.log('Products table PROD-2028EE:', row);

// Search by name
let rows = db.prepare(\"SELECT * FROM products WHERE name LIKE '%Magnetic%Wireless%Charging%Stand%'\").all();
console.log('Products by name:', rows);

// Search more broadly
rows = db.prepare(\"SELECT * FROM products WHERE name LIKE '%Charging%Stand%' OR product_id LIKE '%2028%'\").all();
console.log('Broader search:', rows);

// Also look for rt_variants
rows = db.prepare(\"SELECT * FROM rt_variants WHERE product_id LIKE '%2028%' LIMIT 5\").all();
console.log('rt_variants 2028:', rows);
" 2>&1

